module.exports = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>\ud83d\udc51 WhatsApp Flow Pro - \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645 \u0627\u0644\u0623\u062f\u0645\u0646 \u0627\u0644\u0645\u0631\u0643\u0632\u064a\u0629</title>\n    <link rel=\"icon\" type=\"image/png\" href=\"app-icon.png\">\n    <link rel=\"shortcut icon\" href=\"favicon.ico\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    <style>\n        :root {\n            --bg-main: #090d16;\n            --card-bg: #111827;\n            --card-border: rgba(255, 255, 255, 0.08);\n            --primary: #10b981;\n            --primary-glow: rgba(16, 185, 129, 0.35);\n            --accent: #d97706;\n            --danger: #ef4444;\n            --info: #3b82f6;\n            --text-main: #f3f4f6;\n            --text-muted: #9ca3af;\n            --radius-lg: 18px;\n            --radius-md: 12px;\n            --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n        }\n\n        * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Cairo', sans-serif; }\n\n        body {\n            background: radial-gradient(circle at top right, #064e3b 0%, #090d16 50%, #030712 100%);\n            color: var(--text-main);\n            min-height: 100vh;\n            padding: 24px 20px;\n            display: flex;\n            justify-content: center;\n        }\n\n        .container { width: 100%; max-width: 1280px; display: flex; flex-direction: column; gap: 22px; }\n\n        .card {\n            background: rgba(17, 24, 39, 0.85);\n            backdrop-filter: blur(14px);\n            border: 1px solid var(--card-border);\n            border-radius: var(--radius-lg);\n            padding: 22px 24px;\n            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);\n        }\n\n        .header-card { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }\n        .brand-box { display: flex; align-items: center; gap: 16px; }\n        .brand-icon { width: 52px; height: 52px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n        .brand-icon img { width: 48px; height: 48px; object-fit: contain; filter: drop-shadow(0 4px 14px rgba(16, 185, 129, 0.5)); }\n        .brand-title { font-size: 1.35rem; font-weight: 900; color: #fff; display: flex; align-items: center; gap: 8px; }\n        .badge-pro { background: linear-gradient(135deg, #10b981, #059669); color: white; padding: 2px 8px; border-radius: 6px; font-size: 0.72rem; font-weight: 800; }\n        .header-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n\n        .btn {\n            display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n            padding: 9px 16px; border-radius: var(--radius-md); font-size: 0.88rem; font-weight: 700;\n            cursor: pointer; border: 1px solid transparent; transition: var(--transition); text-decoration: none; outline: none;\n        }\n        .btn-primary { background: linear-gradient(135deg, #10b981, #059669); color: white; box-shadow: 0 4px 14px var(--primary-glow); }\n        .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(16, 185, 129, 0.5); }\n        .btn-secondary { background: rgba(255, 255, 255, 0.06); color: var(--text-main); border-color: var(--card-border); }\n        .btn-secondary:hover { background: rgba(255, 255, 255, 0.1); color: white; }\n        .btn-danger { background: rgba(239, 68, 68, 0.15); color: #f87171; border-color: rgba(239, 68, 68, 0.3); }\n        .btn-danger:hover { background: #ef4444; color: white; }\n        .btn-warning { background: rgba(217, 119, 6, 0.15); color: #fbbf24; border-color: rgba(217, 119, 6, 0.3); }\n        .btn-warning:hover { background: #d97706; color: white; }\n        .btn-sm { padding: 5px 10px; font-size: 0.78rem; border-radius: 8px; }\n\n        .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; }\n        .stat-card {\n            background: rgba(17, 24, 39, 0.7); border: 1px solid var(--card-border);\n            border-radius: var(--radius-md); padding: 18px 20px; display: flex; align-items: center; justify-content: space-between; transition: var(--transition);\n        }\n        .stat-card:hover { border-color: rgba(16, 185, 129, 0.3); transform: translateY(-2px); }\n        .stat-info h4 { font-size: 0.82rem; color: var(--text-muted); font-weight: 600; margin-bottom: 6px; }\n        .stat-info .stat-value { font-size: 1.7rem; font-weight: 900; color: white; line-height: 1.1; }\n        .stat-icon { width: 46px; height: 46px; border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 1.3rem; }\n\n        .controls-bar { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; }\n        .search-box {\n            display: flex; align-items: center; gap: 10px; background: rgba(0, 0, 0, 0.25);\n            border: 1px solid var(--card-border); border-radius: var(--radius-md); padding: 8px 14px; flex: 1; min-width: 260px; max-width: 450px;\n        }\n        .search-box input { background: transparent; border: none; outline: none; color: white; font-size: 0.88rem; width: 100%; }\n        .filter-group { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n        select { background: #1f2937; color: white; border: 1px solid var(--card-border); border-radius: var(--radius-md); padding: 8px 12px; font-size: 0.85rem; outline: none; cursor: pointer; }\n\n        .table-responsive { overflow-x: auto; border: 1px solid var(--card-border); border-radius: var(--radius-md); background: rgba(15, 23, 42, 0.6); }\n        table { width: 100%; border-collapse: collapse; text-align: right; font-size: 0.84rem; }\n        th { background: #111827; padding: 13px 14px; font-weight: 800; color: var(--text-muted); border-bottom: 1px solid var(--card-border); white-space: nowrap; }\n        td { padding: 13px 14px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); vertical-align: middle; }\n        tr:hover td { background: rgba(255, 255, 255, 0.02); }\n\n        .badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 6px; font-size: 0.72rem; font-weight: 800; }\n        .badge-success { background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.3); }\n        .badge-danger { background: rgba(239, 68, 68, 0.15); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.3); }\n        .badge-warning { background: rgba(217, 119, 6, 0.15); color: #fbbf24; border: 1px solid rgba(217, 119, 6, 0.3); }\n        .badge-info { background: rgba(59, 130, 246, 0.15); color: #60a5fa; border: 1px solid rgba(59, 130, 246, 0.3); }\n        .badge-purple { background: rgba(168, 85, 247, 0.15); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.3); }\n\n        .client-name { font-weight: 800; color: #ffffff; font-size: 0.9rem; }\n        .client-sub { font-size: 0.75rem; color: var(--text-muted); }\n        .hwid-code { font-family: monospace; font-size: 0.8rem; background: rgba(0, 0, 0, 0.3); padding: 3px 6px; border-radius: 4px; border: 1px solid rgba(255, 255, 255, 0.08); color: #a7f3d0; display: inline-flex; align-items: center; gap: 6px; }\n        .action-btns { display: flex; align-items: center; gap: 6px; flex-wrap: nowrap; }\n\n        .modal-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.75); backdrop-filter: blur(8px); display: none; align-items: center; justify-content: center; z-index: 1000; padding: 20px; }\n        .modal-card { background: #111827; border: 1px solid var(--card-border); border-radius: var(--radius-lg); width: 100%; max-width: 520px; padding: 26px; box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6); display: flex; flex-direction: column; gap: 18px; }\n        .modal-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--card-border); padding-bottom: 14px; }\n        .modal-header h3 { font-size: 1.15rem; font-weight: 800; color: white; display: flex; align-items: center; gap: 10px; }\n        .modal-close { background: none; border: none; color: var(--text-muted); font-size: 1.2rem; cursor: pointer; }\n        .modal-close:hover { color: white; }\n\n        .form-group { display: flex; flex-direction: column; gap: 6px; }\n        .form-group label { font-size: 0.82rem; font-weight: 700; color: var(--text-muted); }\n        .form-control { background: #1f2937; border: 1px solid var(--card-border); border-radius: var(--radius-md); padding: 10px 14px; color: white; font-size: 0.88rem; outline: none; }\n        .form-control:focus { border-color: var(--primary); box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.2); }\n\n        .login-gate { position: fixed; inset: 0; background: radial-gradient(circle at top, #064e3b 0%, #090d16 60%, #030712 100%); display: flex; align-items: center; justify-content: center; z-index: 2000; padding: 20px; }\n        .login-card { background: rgba(17, 24, 39, 0.9); backdrop-filter: blur(16px); border: 1px solid var(--card-border); border-radius: 22px; width: 100%; max-width: 440px; padding: 34px 30px; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 20px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.7); }\n        .toast { position: fixed; bottom: 24px; left: 24px; background: #1f2937; color: #fff; padding: 14px 20px; border-radius: 12px; border-right: 5px solid var(--primary); box-shadow: 0 10px 30px rgba(0,0,0,0.5); display: none; z-index: 3000; font-weight: 700; font-size: 0.88rem; }\n    </style>\n</head>\n<body>\n\n<div class=\"login-gate\" id=\"loginGate\">\n    <div class=\"login-card\">\n        <div class=\"brand-icon\" style=\"width:68px;height:68px;\">\n            <img src=\"app-icon.png\" style=\"width:64px;height:64px;\" alt=\"Logo\">\n        </div>\n        <div>\n            <h2 style=\"font-size:1.45rem;font-weight:900;color:#fff;margin-bottom:6px\">WhatsApp Flow Pro</h2>\n            <div style=\"color:var(--text-muted);font-size:0.85rem\">\ud83d\udc51 \u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0623\u062f\u0645\u0646 \u0627\u0644\u0645\u0631\u0643\u0632\u064a\u0629 \u0644\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u062a\u0631\u0627\u062e\u064a\u0635 \u0648\u0627\u0644\u0645\u0634\u062a\u0631\u0643\u064a\u0646</div>\n        </div>\n        <div style=\"width:100%;display:flex;flex-direction:column;gap:12px;text-align:right\">\n            <div class=\"form-group\">\n                <label>\ud83d\udd11 \u0631\u0645\u0632 \u0645\u0631\u0648\u0631 \u0627\u0644\u0623\u062f\u0645\u0646 (Admin PIN):</label>\n                <input type=\"password\" id=\"loginPin\" class=\"form-control\" placeholder=\"\u0623\u062f\u062e\u0644 \u0631\u0645\u0632 \u0627\u0644\u0645\u0631\u0648\u0631...\" onkeydown=\"if(event.key==='Enter') doLogin()\">\n            </div>\n            <button class=\"btn btn-primary\" style=\"width:100%;padding:12px\" onclick=\"doLogin()\">\n                <i class=\"fa-solid fa-lock-open\"></i> \u062f\u062e\u0648\u0644 \u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u062d\u0643\u0645\n            </button>\n            <div id=\"loginError\" style=\"color:#f87171;font-size:0.8rem;display:none\"></div>\n        </div>\n        <div style=\"font-size:0.75rem;color:#64748b\">\u0631\u0645\u0632 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a: <code>admin2026</code></div>\n    </div>\n</div>\n\n<div class=\"container\" id=\"mainApp\" style=\"display:none\">\n    <header class=\"card header-card\">\n        <div class=\"brand-box\">\n            <div class=\"brand-icon\">\n                <img src=\"app-icon.png\" alt=\"Logo\">\n            </div>\n            <div>\n                <div class=\"brand-title\">\n                    WhatsApp Flow <span class=\"badge-pro\">MASTER CLOUD</span>\n                </div>\n                <div style=\"font-size:0.78rem;color:var(--text-muted)\">\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u062d\u0643\u0645 \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u064a\u0629 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0639\u0646 \u0628\u064f\u0639\u062f</div>\n            </div>\n        </div>\n\n        <div class=\"header-actions\">\n            <button class=\"btn btn-secondary btn-sm\" onclick=\"openBroadcastModal()\">\n                <i class=\"fa-solid fa-bullhorn\" style=\"color:var(--accent)\"></i> \u062a\u0646\u0628\u064a\u0647 \u0639\u0627\u0645 \u0644\u0644\u0628\u0631\u0627\u0645\u062c\n            </button>\n            <button class=\"btn btn-secondary btn-sm\" onclick=\"openChangePasswordModal()\">\n                <i class=\"fa-solid fa-key\"></i> \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0631\u0645\u0632\n            </button>\n            <button class=\"btn btn-danger btn-sm\" onclick=\"doLogout()\">\n                <i class=\"fa-solid fa-right-from-bracket\"></i> \u062e\u0631\u0648\u062c\n            </button>\n        </div>\n    </header>\n\n    <div class=\"stats-grid\">\n        <div class=\"stat-card\">\n            <div class=\"stat-info\">\n                <h4>\ud83d\udc65 \u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0639\u0645\u0644\u0627\u0621</h4>\n                <div class=\"stat-value\" id=\"statTotal\">0</div>\n            </div>\n            <div class=\"stat-icon\" style=\"background:rgba(59,130,246,0.15);color:#60a5fa\">\n                <i class=\"fa-solid fa-users\"></i>\n            </div>\n        </div>\n        <div class=\"stat-card\">\n            <div class=\"stat-info\">\n                <h4>\ud83d\udfe2 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u064a\u0646 \u0627\u0644\u0646\u0634\u0637\u064a\u0646</h4>\n                <div class=\"stat-value\" id=\"statActive\" style=\"color:#34d399\">0</div>\n            </div>\n            <div class=\"stat-icon\" style=\"background:rgba(16,185,129,0.15);color:#34d399\">\n                <i class=\"fa-solid fa-circle-check\"></i>\n            </div>\n        </div>\n        <div class=\"stat-card\">\n            <div class=\"stat-info\">\n                <h4>\ud83d\udd34 \u0627\u0644\u0645\u0639\u0644\u0642\u064a\u0646 / \u0627\u0644\u0645\u062d\u0638\u0648\u0631\u064a\u0646</h4>\n                <div class=\"stat-value\" id=\"statSuspended\" style=\"color:#f87171\">0</div>\n            </div>\n            <div class=\"stat-icon\" style=\"background:rgba(239,68,68,0.15);color:#f87171\">\n                <i class=\"fa-solid fa-ban\"></i>\n            </div>\n        </div>\n        <div class=\"stat-card\">\n            <div class=\"stat-info\">\n                <h4>\u231b \u0645\u0646\u062a\u0647\u064a\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629</h4>\n                <div class=\"stat-value\" id=\"statExpired\" style=\"color:#fbbf24\">0</div>\n            </div>\n            <div class=\"stat-icon\" style=\"background:rgba(217,119,6,0.15);color:#fbbf24\">\n                <i class=\"fa-solid fa-clock-rotate-left\"></i>\n            </div>\n        </div>\n        <div class=\"stat-card\">\n            <div class=\"stat-info\">\n                <h4>\u26a1 \u0634\u0648\u0647\u062f\u0648\u0627 \u0627\u0644\u064a\u0648\u0645 (24h)</h4>\n                <div class=\"stat-value\" id=\"statOnline\" style=\"color:#c084fc\">0</div>\n            </div>\n            <div class=\"stat-icon\" style=\"background:rgba(168,85,247,0.15);color:#c084fc\">\n                <i class=\"fa-solid fa-bolt\"></i>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"card\" style=\"display:flex;flex-direction:column;gap:16px;\">\n        <div class=\"controls-bar\">\n            <div class=\"search-box\">\n                <i class=\"fa-solid fa-magnifying-glass\" style=\"color:var(--text-muted)\"></i>\n                <input type=\"text\" id=\"searchInput\" placeholder=\"\u0628\u062d\u062b \u0628\u0627\u0633\u0645 \u0627\u0644\u0639\u0645\u064a\u0644\u060c \u0627\u0644\u0647\u0627\u062a\u0641\u060c HWID\u060c \u0623\u0648 \u0627\u0644\u0634\u0631\u0643\u0629...\" oninput=\"loadClients()\">\n            </div>\n\n            <div class=\"filter-group\">\n                <select id=\"statusFilter\" onchange=\"loadClients()\">\n                    <option value=\"all\">\u0643\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a</option>\n                    <option value=\"active\">\ud83d\udfe2 \u0627\u0644\u0646\u0634\u0637\u064a\u0646 \u0641\u0642\u0637</option>\n                    <option value=\"suspended\">\ud83d\udd34 \u0627\u0644\u0645\u0639\u0644\u0642\u064a\u0646 \u0641\u0642\u0637</option>\n                    <option value=\"expired\">\u231b \u0627\u0644\u0645\u0646\u062a\u0647\u064a\u064a\u0646 \u0641\u0642\u0637</option>\n                </select>\n\n                <select id=\"planFilter\" onchange=\"loadClients()\">\n                    <option value=\"all\">\u0643\u0644 \u0627\u0644\u0628\u0627\u0642\u0627\u062a</option>\n                    <option value=\"trial\">\u062a\u062c\u0631\u064a\u0628\u064a (Trial)</option>\n                    <option value=\"1month\">\u0634\u0647\u0631\u064a (1 Month)</option>\n                    <option value=\"1year\">\u0633\u0646\u0648\u064a (1 Year)</option>\n                    <option value=\"lifetime\">\u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 (Lifetime)</option>\n                </select>\n\n                <button class=\"btn btn-primary\" onclick=\"openAddClientModal()\">\n                    <i class=\"fa-solid fa-user-plus\"></i> \u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064a\u0644 / \u062a\u0631\u062e\u064a\u0635\n                </button>\n                <button class=\"btn btn-secondary\" onclick=\"loadClients()\" title=\"\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0642\u0627\u0626\u0645\u0629\">\n                    <i class=\"fa-solid fa-rotate\"></i>\n                </button>\n            </div>\n        </div>\n\n        <div class=\"table-responsive\">\n            <table>\n                <thead>\n                    <tr>\n                        <th>\u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0627\u0644\u0646\u0634\u0627\u0637</th>\n                        <th>\u0627\u0644\u0647\u0627\u062a\u0641</th>\n                        <th>\u0628\u0635\u0645\u0629 \u0627\u0644\u062c\u0647\u0627\u0632 (HWID)</th>\n                        <th>\u0627\u0644\u0628\u0627\u0642\u0629</th>\n                        <th>\u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629</th>\n                        <th>\u0622\u062e\u0631 \u0638\u0647\u0648\u0631</th>\n                        <th>\u0627\u0644\u062d\u0627\u0644\u0629</th>\n                        <th style=\"text-align:center\">\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062a\u062d\u0643\u0645</th>\n                    </tr>\n                </thead>\n                <tbody id=\"clientsTableBody\">\n                    <tr>\n                        <td colspan=\"8\" style=\"text-align:center;padding:30px;color:var(--text-muted)\">\n                            <i class=\"fa-solid fa-spinner fa-spin\" style=\"font-size:1.5rem;color:var(--primary)\"></i>\n                            <div style=\"margin-top:8px\">\u062c\u0627\u0631\u064a \u062a\u062d\u0645\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u0621...</div>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n<!-- Modals -->\n<div class=\"modal-overlay\" id=\"clientModal\">\n    <div class=\"modal-card\">\n        <div class=\"modal-header\">\n            <h3 id=\"modalTitle\"><i class=\"fa-solid fa-user-plus\" style=\"color:var(--primary)\"></i> \u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064a\u0644 \u0648\u062a\u0631\u062e\u064a\u0635 \u062c\u062f\u064a\u062f</h3>\n            <button class=\"modal-close\" onclick=\"closeModal('clientModal')\">&times;</button>\n        </div>\n        <div class=\"form-group\">\n            <label>\ud83d\udd11 \u0628\u0635\u0645\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0639\u0645\u064a\u0644 (HWID) * :</label>\n            <input type=\"text\" id=\"mHwid\" class=\"form-control\" placeholder=\"WA-XXXX-XXXX-XXXX\">\n        </div>\n        <div class=\"form-group\">\n            <label>\ud83d\udc64 \u0627\u0633\u0645 \u0627\u0644\u0639\u0645\u064a\u0644:</label>\n            <input type=\"text\" id=\"mName\" class=\"form-control\" placeholder=\"\u0645\u062b\u0627\u0644: \u0623\u062d\u0645\u062f \u0645\u062d\u0645\u062f\">\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\">\n            <div class=\"form-group\">\n                <label>\ud83c\udfe2 \u0627\u0633\u0645 \u0627\u0644\u0634\u0631\u0643\u0629 / \u0627\u0644\u0646\u0634\u0627\u0637:</label>\n                <input type=\"text\" id=\"mCompany\" class=\"form-control\" placeholder=\"\u0645\u062b\u0627\u0644: \u0645\u062a\u062c\u0631 \u0627\u0644\u0623\u0646\u0627\u0642\u0629\">\n            </div>\n            <div class=\"form-group\">\n                <label>\ud83d\udcf1 \u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641:</label>\n                <input type=\"text\" id=\"mPhone\" class=\"form-control\" placeholder=\"01012345678\">\n            </div>\n        </div>\n        <div class=\"form-group\">\n            <label>\ud83d\udce6 \u0628\u0627\u0642\u0629 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643:</label>\n            <select id=\"mPlan\" class=\"form-control\" onchange=\"toggleCustomDays()\">\n                <option value=\"lifetime\">\u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 (Lifetime - \u063a\u064a\u0631 \u0645\u062d\u062f\u0648\u062f)</option>\n                <option value=\"1year\">\u0633\u0646\u0648\u064a (1 Year - 365 \u064a\u0648\u0645)</option>\n                <option value=\"1month\">\u0634\u0647\u0631\u064a (1 Month - 30 \u064a\u0648\u0645)</option>\n                <option value=\"trial\">\u062a\u062c\u0631\u064a\u0628\u064a (Trial - 3 \u0623\u064a\u0627\u0645)</option>\n                <option value=\"custom\">\u0623\u064a\u0627\u0645 \u0645\u062e\u0635\u0635\u0629 (Custom Days)</option>\n            </select>\n        </div>\n        <div class=\"form-group\" id=\"mCustomDaysGroup\" style=\"display:none\">\n            <label>\u23f3 \u0639\u062f\u062f \u0627\u0644\u0623\u064a\u0627\u0645:</label>\n            <input type=\"number\" id=\"mDays\" class=\"form-control\" placeholder=\"\u0645\u062b\u0627\u0644: 90\">\n        </div>\n        <div class=\"form-group\">\n            <label>\ud83d\udcdd \u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0625\u0636\u0627\u0641\u064a\u0629 (\u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u0623\u062f\u0645\u0646):</label>\n            <input type=\"text\" id=\"mNotes\" class=\"form-control\" placeholder=\"\u0645\u062b\u0627\u0644: \u062f\u0641\u0639 \u0639\u0628\u0631 \u0641\u0648\u062f\u0627\u0641\u0648\u0646 \u0643\u0627\u0634\">\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:10px;margin-top:10px\">\n            <button class=\"btn btn-secondary\" onclick=\"closeModal('clientModal')\">\u0625\u0644\u063a\u0627\u0621</button>\n            <button class=\"btn btn-primary\" onclick=\"saveClientModal()\">\u062d\u0641\u0638 \u0648\u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u062a\u0631\u062e\u064a\u0635</button>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal-overlay\" id=\"renewModal\">\n    <div class=\"modal-card\">\n        <div class=\"modal-header\">\n            <h3><i class=\"fa-solid fa-clock-rotate-left\" style=\"color:var(--accent)\"></i> \u062a\u0645\u062f\u064a\u062f / \u062a\u062c\u062f\u064a\u062f \u0627\u0634\u062a\u0631\u0627\u0643 \u0627\u0644\u0639\u0645\u064a\u0644</h3>\n            <button class=\"modal-close\" onclick=\"closeModal('renewModal')\">&times;</button>\n        </div>\n        <div style=\"background:rgba(255,255,255,0.04);padding:12px;border-radius:10px;font-size:0.85rem\">\n            <div><strong>\u0627\u0644\u0639\u0645\u064a\u0644:</strong> <span id=\"rClientName\">\u2014</span></div>\n            <div><strong>\u0628\u0635\u0645\u0629 \u0627\u0644\u062c\u0647\u0627\u0632:</strong> <code id=\"rHwid\">\u2014</code></div>\n        </div>\n        <div class=\"form-group\">\n            <label>\ud83d\udce6 \u062d\u062f\u062f \u0645\u062f\u0629 \u0627\u0644\u062a\u062c\u062f\u064a\u062f \u0627\u0644\u062c\u062f\u064a\u062f\u0629:</label>\n            <select id=\"rPlan\" class=\"form-control\">\n                <option value=\"1month\">\u062a\u062c\u062f\u064a\u062f \u0644\u0634\u0647\u0631 \u0625\u0636\u0627\u0641\u064a (+30 \u064a\u0648\u0645)</option>\n                <option value=\"1year\">\u062a\u062c\u062f\u064a\u062f \u0644\u0633\u0646\u0629 \u0643\u0627\u0645\u0644\u0629 (+365 \u064a\u0648\u0645)</option>\n                <option value=\"lifetime\">\u062a\u0631\u0642\u064a\u0629 \u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u062f\u0627\u0626\u0645 (\u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629)</option>\n                <option value=\"trial\">\u062a\u062c\u0631\u0628\u0629 3 \u0623\u064a\u0627\u0645</option>\n            </select>\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:10px;margin-top:10px\">\n            <button class=\"btn btn-secondary\" onclick=\"closeModal('renewModal')\">\u0625\u0644\u063a\u0627\u0621</button>\n            <button class=\"btn btn-primary\" onclick=\"confirmRenew()\">\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062a\u062c\u062f\u064a\u062f \u0648\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062d\u0633\u0627\u0628</button>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal-overlay\" id=\"broadcastModal\">\n    <div class=\"modal-card\">\n        <div class=\"modal-header\">\n            <h3><i class=\"fa-solid fa-bullhorn\" style=\"color:var(--accent)\"></i> \u0625\u0631\u0633\u0627\u0644 \u062a\u0646\u0628\u064a\u0647 \u0639\u0627\u0645 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u0631\u0627\u0645\u062c</h3>\n            <button class=\"modal-close\" onclick=\"closeModal('broadcastModal')\">&times;</button>\n        </div>\n        <p style=\"font-size:0.82rem;color:var(--text-muted)\">\n            \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0633\u062a\u0643\u062a\u0628\u0647\u0627 \u0647\u0646\u0627 \u0633\u062a\u0638\u0647\u0631 \u0641\u064a \u0634\u0631\u064a\u0637 \u0639\u0644\u0648\u064a \u0628\u0627\u0631\u0632 \u062f\u0627\u062e\u0644 \u062c\u0645\u064a\u0639 \u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0639\u0646\u062f \u062a\u0634\u063a\u064a\u0644\u0647\u0645 \u0644\u0644\u0628\u0631\u0646\u0627\u0645\u062c.\n        </p>\n        <div class=\"form-group\">\n            <label>\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u0646\u0628\u064a\u0647:</label>\n            <select id=\"bcEnabled\" class=\"form-control\">\n                <option value=\"true\">\ud83d\udfe2 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0644\u0644\u062c\u0645\u064a\u0639</option>\n                <option value=\"false\">\u26aa \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u062a\u0646\u0628\u064a\u0647</option>\n            </select>\n        </div>\n        <div class=\"form-group\">\n            <label>\u0646\u0648\u0639 \u0627\u0644\u062a\u0646\u0628\u064a\u0647:</label>\n            <select id=\"bcType\" class=\"form-control\">\n                <option value=\"info\">\u0645\u0639\u0644\u0648\u0645\u0629 \u0639\u0627\u0645\u0629 (\u0623\u0632\u0631\u0642)</option>\n                <option value=\"warning\">\u062a\u0646\u0628\u064a\u0647 \u0647\u0627\u0645 / \u0635\u064a\u0627\u0646\u0629 (\u0623\u0635\u0641\u0631)</option>\n                <option value=\"success\">\u0639\u0631\u0636 \u062e\u0627\u0635 / \u062a\u062d\u062f\u064a\u062b (\u0623\u062e\u0636\u0631)</option>\n            </select>\n        </div>\n        <div class=\"form-group\">\n            <label>\u0646\u0635 \u0627\u0644\u062a\u0646\u0628\u064a\u0647:</label>\n            <textarea id=\"bcText\" class=\"form-control\" rows=\"3\" placeholder=\"\u0645\u062b\u0627\u0644: \u062a\u0646\u0628\u064a\u0647 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u064a\u0646\u060c \u062a\u0645 \u0625\u0637\u0644\u0627\u0642 \u062a\u062d\u062f\u064a\u062b \u062c\u062f\u064a\u062f \u0644\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0628\u0645\u064a\u0632\u0627\u062a \u0645\u0636\u0627\u0639\u0641\u0629...\"></textarea>\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:10px;margin-top:10px\">\n            <button class=\"btn btn-secondary\" onclick=\"closeModal('broadcastModal')\">\u0625\u0644\u063a\u0627\u0621</button>\n            <button class=\"btn btn-primary\" onclick=\"saveBroadcast()\">\u062d\u0641\u0638 \u0648\u0628\u062b \u0627\u0644\u062a\u0646\u0628\u064a\u0647</button>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal-overlay\" id=\"passwordModal\">\n    <div class=\"modal-card\">\n        <div class=\"modal-header\">\n            <h3><i class=\"fa-solid fa-key\" style=\"color:var(--primary)\"></i> \u062a\u063a\u064a\u064a\u0631 \u0631\u0645\u0632 \u0645\u0631\u0648\u0631 \u0627\u0644\u0623\u062f\u0645\u0646</h3>\n            <button class=\"modal-close\" onclick=\"closeModal('passwordModal')\">&times;</button>\n        </div>\n        <div class=\"form-group\">\n            <label>\u0631\u0645\u0632 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f:</label>\n            <input type=\"password\" id=\"newPin\" class=\"form-control\" placeholder=\"\u0623\u062f\u062e\u0644 4 \u062e\u0627\u0646\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644...\">\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:10px;margin-top:10px\">\n            <button class=\"btn btn-secondary\" onclick=\"closeModal('passwordModal')\">\u0625\u0644\u063a\u0627\u0621</button>\n            <button class=\"btn btn-primary\" onclick=\"saveNewPassword()\">\u062d\u0641\u0638 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u062c\u062f\u064a\u062f</button>\n        </div>\n    </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nlet adminToken = localStorage.getItem('flow_admin_token') || '';\nlet currentClients = [];\nlet activeTargetHwid = null;\n\nwindow.addEventListener('DOMContentLoaded', () => {\n    if (adminToken) {\n        verifySession();\n    } else {\n        showLogin();\n    }\n});\n\nfunction showLogin() {\n    document.getElementById('loginGate').style.display = 'flex';\n    document.getElementById('mainApp').style.display = 'none';\n}\n\nfunction showApp() {\n    document.getElementById('loginGate').style.display = 'none';\n    document.getElementById('mainApp').style.display = 'flex';\n    loadStats();\n    loadClients();\n}\n\nasync function doLogin() {\n    const pin = document.getElementById('loginPin').value.trim();\n    const errDiv = document.getElementById('loginError');\n    errDiv.style.display = 'none';\n\n    if (!pin) {\n        errDiv.innerText = '\u064a\u0631\u062c\u0649 \u0625\u062f\u062e\u0627\u0644 \u0631\u0645\u0632 \u0627\u0644\u0645\u0631\u0648\u0631';\n        errDiv.style.display = 'block';\n        return;\n    }\n\n    try {\n        const res = await fetch('/api/auth/login', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ pin })\n        });\n        const data = await res.json();\n        if (data.success) {\n            adminToken = data.token;\n            localStorage.setItem('flow_admin_token', adminToken);\n            showApp();\n            showToast('\ud83c\udf89 \u0645\u0631\u062d\u0628\u0627\u064b \u0628\u0643 \u0641\u064a \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645 \u0627\u0644\u0623\u062f\u0645\u0646 \u0627\u0644\u0645\u0631\u0643\u0632\u064a\u0629!');\n        } else {\n            errDiv.innerText = data.error || '\u0631\u0645\u0632 \u0627\u0644\u0645\u0631\u0648\u0631 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d';\n            errDiv.style.display = 'block';\n        }\n    } catch (e) {\n        errDiv.innerText = '\u0641\u0634\u0644 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0633\u064a\u0631\u0641\u0631';\n        errDiv.style.display = 'block';\n    }\n}\n\nasync function verifySession() {\n    try {\n        const res = await fetch('/api/admin/stats', {\n            headers: { 'Authorization': 'Bearer ' + adminToken }\n        });\n        if (res.ok) {\n            showApp();\n        } else {\n            localStorage.removeItem('flow_admin_token');\n            showLogin();\n        }\n    } catch (_) {\n        showLogin();\n    }\n}\n\nfunction doLogout() {\n    localStorage.removeItem('flow_admin_token');\n    adminToken = '';\n    showLogin();\n    showToast('\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \u0628\u0646\u062c\u0627\u062d');\n}\n\nasync function loadStats() {\n    try {\n        const res = await fetch('/api/admin/stats', {\n            headers: { 'Authorization': 'Bearer ' + adminToken }\n        });\n        const data = await res.json();\n        if (data.success) {\n            document.getElementById('statTotal').innerText = data.stats.total || 0;\n            document.getElementById('statActive').innerText = data.stats.active || 0;\n            document.getElementById('statSuspended').innerText = data.stats.suspended || 0;\n            document.getElementById('statExpired').innerText = data.stats.expired || 0;\n            document.getElementById('statOnline').innerText = data.stats.onlineRecently || 0;\n        }\n    } catch (e) {\n        console.error('Error loading stats:', e);\n    }\n}\n\nasync function loadClients() {\n    const search = document.getElementById('searchInput').value.trim();\n    const status = document.getElementById('statusFilter').value;\n    const plan = document.getElementById('planFilter').value;\n    const tbody = document.getElementById('clientsTableBody');\n\n    try {\n        const params = new URLSearchParams({ search, status, plan });\n        const res = await fetch('/api/admin/clients?' + params.toString(), {\n            headers: { 'Authorization': 'Bearer ' + adminToken }\n        });\n        const data = await res.json();\n        if (data.success) {\n            currentClients = data.clients || [];\n            renderTable(currentClients);\n        }\n    } catch (e) {\n        tbody.innerHTML = '<tr><td colspan=\"8\" style=\"text-align:center;color:#f87171;padding:20px\">\u062e\u0637\u0623 \u0641\u064a \u062c\u0644\u0628 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u0621</td></tr>';\n    }\n}\n\nfunction renderTable(clients) {\n    const tbody = document.getElementById('clientsTableBody');\n    if (!clients || clients.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"8\" style=\"text-align:center;color:var(--text-muted);padding:30px\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0645\u0644\u0627\u0621 \u0645\u0637\u0627\u0628\u0642\u064a\u0646 \u0644\u0644\u0628\u062d\u062b \u062d\u0627\u0644\u064a\u0627\u064b</td></tr>';\n        return;\n    }\n\n    const planLabels = {\n        'trial': '<span class=\"badge badge-warning\"><i class=\"fa-solid fa-flask\"></i> \u062a\u062c\u0631\u064a\u0628\u064a (3 \u0623\u064a\u0627\u0645)</span>',\n        '1month': '<span class=\"badge badge-info\"><i class=\"fa-solid fa-calendar\"></i> \u0634\u0647\u0631\u064a</span>',\n        '1year': '<span class=\"badge badge-purple\"><i class=\"fa-solid fa-crown\"></i> \u0633\u0646\u0648\u064a</span>',\n        'lifetime': '<span class=\"badge badge-success\"><i class=\"fa-solid fa-infinity\"></i> \u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629</span>'\n    };\n\n    tbody.innerHTML = clients.map(c => {\n        const isSuspended = c.computedStatus === 'suspended';\n        const isExpired = c.computedStatus === 'expired';\n\n        let statusBadge = '<span class=\"badge badge-success\">\ud83d\udfe2 \u0646\u0634\u0637</span>';\n        if (isSuspended) statusBadge = '<span class=\"badge badge-danger\">\ud83d\udd34 \u0645\u0639\u0644\u0642 / \u0645\u062d\u0638\u0648\u0631</span>';\n        else if (isExpired) statusBadge = '<span class=\"badge badge-warning\">\u231b \u0645\u0646\u062a\u0647\u064a</span>';\n\n        const rawPhone = (c.phone || '').replace(/[^0-9]/g, '');\n        const waLink = rawPhone ? `<a href=\"https://wa.me/${rawPhone}\" target=\"_blank\" class=\"btn btn-sm btn-secondary\" style=\"color:#34d399\" title=\"\u0645\u062d\u0627\u062f\u062b\u0629 \u0648\u0627\u062a\u0633\u0627\u0628 \u0645\u0628\u0627\u0634\u0631\u0629\"><i class=\"fa-brands fa-whatsapp\"></i> ${c.phone}</a>` : '<span style=\"color:#64748b\">\u2014</span>';\n\n        let lastSeenText = '<span style=\"color:#64748b\">\u0644\u0645 \u064a\u0633\u062c\u0644 \u062f\u062e\u0648\u0644</span>';\n        if (c.lastSeenAt) {\n            const diffMin = Math.round((new Date() - new Date(c.lastSeenAt)) / 60000);\n            if (diffMin < 5) lastSeenText = '<span style=\"color:#34d399;font-weight:700\">\u0645\u062a\u0635\u0644 \u0627\u0644\u0622\u0646 \u26a1</span>';\n            else if (diffMin < 60) lastSeenText = `\u0645\u0646\u0630 ${diffMin} \u062f\u0642\u064a\u0642\u0629`;\n            else if (diffMin < 1440) lastSeenText = `\u0645\u0646\u0630 ${Math.round(diffMin/60)} \u0633\u0627\u0639\u0629`;\n            else lastSeenText = new Date(c.lastSeenAt).toLocaleDateString('ar-EG');\n        }\n\n        const toggleBtnIcon = isSuspended ? 'fa-play' : 'fa-ban';\n        const toggleBtnClass = isSuspended ? 'btn-primary' : 'btn-danger';\n        const toggleBtnTitle = isSuspended ? '\u062a\u0641\u0639\u064a\u0644 \u0648\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062d\u0638\u0631' : '\u062d\u0638\u0631 / \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0641\u0648\u0631\u0627\u064b';\n\n        return `\n            <tr>\n                <td>\n                    <div class=\"client-name\">${escapeHtml(c.name || '\u0639\u0645\u064a\u0644 \u0645\u0633\u062c\u0644')}</div>\n                    <div class=\"client-sub\">${escapeHtml(c.company || '\u0646\u0634\u0627\u0637 \u062a\u062c\u0627\u0631\u064a')}</div>\n                </td>\n                <td>${waLink}</td>\n                <td>\n                    <div class=\"hwid-code\" title=\"\u0628\u0635\u0645\u0629 \u0627\u0644\u062c\u0647\u0627\u0632\">\n                        ${c.hwid}\n                        <button onclick=\"copyText('${c.hwid}', '\u062a\u0645 \u0646\u0633\u062e \u0628\u0635\u0645\u0629 \u0627\u0644\u062c\u0647\u0627\u0632')\" style=\"background:none;border:none;color:#94a3b8;cursor:pointer\" title=\"\u0646\u0633\u062e\"><i class=\"fa-regular fa-copy\"></i></button>\n                    </div>\n                </td>\n                <td>${planLabels[c.plan] || planLabels.lifetime}</td>\n                <td>\n                    <div style=\"font-weight:700\">${c.expiry === 'LIFETIME' ? '\u267e\ufe0f \u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629' : c.expiry}</div>\n                    <div style=\"font-size:0.75rem;color:${isExpired ? '#f87171' : 'var(--text-muted)'}\">${c.daysLeft === '\u063a\u064a\u0631 \u0645\u062d\u062f\u0648\u062f' ? '\u063a\u064a\u0631 \u0645\u062d\u062f\u0648\u062f' : '\u0645\u062a\u0628\u0642\u064a: ' + c.daysLeft + ' \u064a\u0648\u0645'}</div>\n                </td>\n                <td>${lastSeenText}</td>\n                <td>${statusBadge}</td>\n                <td style=\"text-align:center\">\n                    <div class=\"action-btns\" style=\"justify-content:center\">\n                        <button class=\"btn btn-sm ${toggleBtnClass}\" onclick=\"toggleClientStatus('${c.hwid}')\" title=\"${toggleBtnTitle}\">\n                            <i class=\"fa-solid ${toggleBtnIcon}\"></i>\n                        </button>\n                        <button class=\"btn btn-sm btn-warning\" onclick=\"openRenewModal('${c.hwid}')\" title=\"\u062a\u0645\u062f\u064a\u062f / \u062a\u062c\u062f\u064a\u062f \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\">\n                            <i class=\"fa-solid fa-clock-rotate-left\"></i>\n                        </button>\n                        <button class=\"btn btn-sm btn-secondary\" onclick=\"copyText('${c.licenseKey}', '\u062a\u0645 \u0646\u0633\u062e \u0643\u0648\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062e\u0627\u0635 \u0628\u0627\u0644\u0639\u0645\u064a\u0644')\" title=\"\u0646\u0633\u062e \u0643\u0648\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644\">\n                            <i class=\"fa-solid fa-key\"></i>\n                        </button>\n                        <button class=\"btn btn-sm btn-secondary\" onclick=\"editClient('${c.hwid}')\" title=\"\u062a\u0639\u062f\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644\">\n                            <i class=\"fa-solid fa-pen-to-square\"></i>\n                        </button>\n                        <button class=\"btn btn-sm btn-danger\" onclick=\"deleteClient('${c.hwid}')\" title=\"\u062d\u0630\u0641 \u0627\u0644\u0639\u0645\u064a\u0644\">\n                            <i class=\"fa-solid fa-trash\"></i>\n                        </button>\n                    </div>\n                </td>\n            </tr>\n        `;\n    }).join('');\n}\n\nasync function toggleClientStatus(hwid) {\n    try {\n        const res = await fetch('/api/admin/clients/' + hwid + '/toggle-status', {\n            method: 'PUT',\n            headers: { 'Authorization': 'Bearer ' + adminToken, 'Content-Type': 'application/json' },\n            body: JSON.stringify({ reason: '\u062a\u0645 \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0645\u0646 \u0642\u0628\u0644 \u0627\u0644\u0625\u062f\u0627\u0631\u0629' })\n        });\n        const data = await res.json();\n        if (data.success) {\n            showToast(data.status === 'suspended' ? '\ud83d\udd12 \u062a\u0645 \u0625\u064a\u0642\u0627\u0641 \u0648\u062d\u0638\u0631 \u0627\u0644\u0639\u0645\u064a\u0644 \u0641\u0648\u0631\u0627\u064b \u0639\u0646 \u0628\u0639\u062f!' : '\u2705 \u062a\u0645 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0639\u0645\u064a\u0644 \u0628\u0646\u062c\u0627\u062d!');\n            loadStats();\n            loadClients();\n        }\n    } catch (e) {\n        showToast('\u062d\u062f\u062b \u062e\u0637\u0623 \u0623\u062b\u0646\u0627\u0621 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u062d\u0627\u0644\u0629');\n    }\n}\n\nfunction openRenewModal(hwid) {\n    const client = currentClients.find(c => c.hwid === hwid);\n    if (!client) return;\n    activeTargetHwid = hwid;\n    document.getElementById('rClientName').innerText = client.name || '\u0639\u0645\u064a\u0644';\n    document.getElementById('rHwid').innerText = hwid;\n    openModal('renewModal');\n}\n\nasync function confirmRenew() {\n    if (!activeTargetHwid) return;\n    const plan = document.getElementById('rPlan').value;\n    try {\n        const res = await fetch('/api/admin/clients/' + activeTargetHwid + '/renew', {\n            method: 'PUT',\n            headers: { 'Authorization': 'Bearer ' + adminToken, 'Content-Type': 'application/json' },\n            body: JSON.stringify({ plan })\n        });\n        const data = await res.json();\n        if (data.success) {\n            closeModal('renewModal');\n            showToast('\ud83c\udf89 \u062a\u0645 \u062a\u062c\u062f\u064a\u062f \u0627\u0634\u062a\u0631\u0627\u0643 \u0627\u0644\u0639\u0645\u064a\u0644 \u0628\u0646\u062c\u0627\u062d \u0648\u062a\u062d\u062f\u064a\u062b \u0635\u0644\u0627\u062d\u064a\u062a\u0647!');\n            loadStats();\n            loadClients();\n        }\n    } catch (e) {\n        showToast('\u062d\u062f\u062b \u062e\u0637\u0623 \u0641\u064a \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u062c\u062f\u064a\u062f');\n    }\n}\n\nfunction openAddClientModal() {\n    activeTargetHwid = null;\n    document.getElementById('modalTitle').innerHTML = '<i class=\"fa-solid fa-user-plus\" style=\"color:var(--primary)\"></i> \u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064a\u0644 \u0648\u062a\u0631\u062e\u064a\u0635 \u062c\u062f\u064a\u062f';\n    document.getElementById('mHwid').value = '';\n    document.getElementById('mHwid').disabled = false;\n    document.getElementById('mName').value = '';\n    document.getElementById('mCompany').value = '';\n    document.getElementById('mPhone').value = '';\n    document.getElementById('mPlan').value = 'lifetime';\n    document.getElementById('mNotes').value = '';\n    toggleCustomDays();\n    openModal('clientModal');\n}\n\nfunction editClient(hwid) {\n    const client = currentClients.find(c => c.hwid === hwid);\n    if (!client) return;\n    activeTargetHwid = hwid;\n    document.getElementById('modalTitle').innerHTML = '<i class=\"fa-solid fa-pen-to-square\" style=\"color:var(--primary)\"></i> \u062a\u0639\u062f\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644';\n    document.getElementById('mHwid').value = client.hwid;\n    document.getElementById('mHwid').disabled = true;\n    document.getElementById('mName').value = client.name || '';\n    document.getElementById('mCompany').value = client.company || '';\n    document.getElementById('mPhone').value = client.phone || '';\n    document.getElementById('mPlan').value = client.plan || 'lifetime';\n    document.getElementById('mNotes').value = client.notes || '';\n    toggleCustomDays();\n    openModal('clientModal');\n}\n\nfunction toggleCustomDays() {\n    const plan = document.getElementById('mPlan').value;\n    document.getElementById('mCustomDaysGroup').style.display = (plan === 'custom') ? 'flex' : 'none';\n}\n\nasync function saveClientModal() {\n    const hwid = document.getElementById('mHwid').value.trim();\n    const name = document.getElementById('mName').value.trim();\n    const company = document.getElementById('mCompany').value.trim();\n    const phone = document.getElementById('mPhone').value.trim();\n    const plan = document.getElementById('mPlan').value;\n    const days = (plan === 'custom') ? parseInt(document.getElementById('mDays').value) : null;\n    const notes = document.getElementById('mNotes').value.trim();\n\n    if (!hwid) {\n        showToast('\u064a\u0631\u062c\u0649 \u0625\u062f\u062e\u0627\u0644 \u0628\u0635\u0645\u0629 \u0627\u0644\u062c\u0647\u0627\u0632 HWID');\n        return;\n    }\n\n    try {\n        const res = await fetch('/api/admin/clients', {\n            method: 'POST',\n            headers: { 'Authorization': 'Bearer ' + adminToken, 'Content-Type': 'application/json' },\n            body: JSON.stringify({ hwid, name, company, phone, plan, days, notes })\n        });\n        const data = await res.json();\n        if (data.success) {\n            closeModal('clientModal');\n            showToast('\u2705 \u062a\u0645 \u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u062a\u0631\u062e\u064a\u0635 \u0628\u0646\u062c\u0627\u062d!');\n            loadStats();\n            loadClients();\n        } else {\n            showToast(data.error || '\u062d\u062f\u062b \u062e\u0637\u0623 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0641\u0638');\n        }\n    } catch (e) {\n        showToast('\u0641\u0634\u0644 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0633\u064a\u0631\u0641\u0631');\n    }\n}\n\nasync function deleteClient(hwid) {\n    if (!confirm('\u0647\u0644 \u0623\u0646\u062a \u0645\u062a\u0623\u0643\u062f \u0645\u0646 \u062d\u0630\u0641 \u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u064a\u0644 \u0645\u0646 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u061f')) return;\n    try {\n        const res = await fetch('/api/admin/clients/' + hwid, {\n            method: 'DELETE',\n            headers: { 'Authorization': 'Bearer ' + adminToken }\n        });\n        const data = await res.json();\n        if (data.success) {\n            showToast('\u062a\u0645 \u062d\u0630\u0641 \u0627\u0644\u0639\u0645\u064a\u0644 \u0628\u0646\u062c\u0627\u062d');\n            loadStats();\n            loadClients();\n        }\n    } catch (e) {\n        showToast('\u062d\u062f\u062b \u062e\u0637\u0623 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0630\u0641');\n    }\n}\n\nasync function openBroadcastModal() {\n    try {\n        const res = await fetch('/api/admin/stats', { headers: { 'Authorization': 'Bearer ' + adminToken } });\n        const data = await res.json();\n        if (data.broadcast) {\n            document.getElementById('bcEnabled').value = data.broadcast.enabled ? 'true' : 'false';\n            document.getElementById('bcType').value = data.broadcast.type || 'info';\n            document.getElementById('bcText').value = data.broadcast.text || '';\n        }\n    } catch (_) {}\n    openModal('broadcastModal');\n}\n\nasync function saveBroadcast() {\n    const enabled = document.getElementById('bcEnabled').value === 'true';\n    const type = document.getElementById('bcType').value;\n    const text = document.getElementById('bcText').value.trim();\n\n    try {\n        const res = await fetch('/api/admin/broadcast', {\n            method: 'POST',\n            headers: { 'Authorization': 'Bearer ' + adminToken, 'Content-Type': 'application/json' },\n            body: JSON.stringify({ enabled, type, text })\n        });\n        const data = await res.json();\n        if (data.success) {\n            closeModal('broadcastModal');\n            showToast('\ud83d\udce2 \u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0648\u0628\u062b \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0644\u062c\u0645\u064a\u0639 \u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u064a\u0646!');\n        }\n    } catch (e) {\n        showToast('\u0641\u0634\u0644 \u062d\u0641\u0638 \u0627\u0644\u062a\u0646\u0628\u064a\u0647');\n    }\n}\n\nfunction openChangePasswordModal() {\n    document.getElementById('newPin').value = '';\n    openModal('passwordModal');\n}\n\nasync function saveNewPassword() {\n    const newPin = document.getElementById('newPin').value.trim();\n    if (!newPin || newPin.length < 4) {\n        showToast('\u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0631\u0645\u0632 4 \u062e\u0627\u0646\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644');\n        return;\n    }\n    try {\n        const res = await fetch('/api/admin/change-password', {\n            method: 'POST',\n            headers: { 'Authorization': 'Bearer ' + adminToken, 'Content-Type': 'application/json' },\n            body: JSON.stringify({ newPin })\n        });\n        const data = await res.json();\n        if (data.success) {\n            adminToken = newPin;\n            localStorage.setItem('flow_admin_token', newPin);\n            closeModal('passwordModal');\n            showToast('\ud83d\udd12 \u062a\u0645 \u062a\u063a\u064a\u064a\u0631 \u0631\u0645\u0632 \u0645\u0631\u0648\u0631 \u0627\u0644\u0623\u062f\u0645\u0646 \u0628\u0646\u062c\u0627\u062d!');\n        }\n    } catch (e) {\n        showToast('\u0641\u0634\u0644 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0631\u0645\u0632');\n    }\n}\n\nfunction openModal(id) { document.getElementById(id).style.display = 'flex'; }\nfunction closeModal(id) { document.getElementById(id).style.display = 'none'; }\n\nfunction copyText(text, msg = '\u062a\u0645 \u0627\u0644\u0646\u0633\u062e') {\n    if (!text) return;\n    navigator.clipboard.writeText(text);\n    showToast(msg);\n}\n\nfunction showToast(msg) {\n    const t = document.getElementById('toast');\n    t.innerText = msg;\n    t.style.display = 'block';\n    setTimeout(() => { t.style.display = 'none'; }, 3200);\n}\n\nfunction escapeHtml(str) {\n    if (!str) return '';\n    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n}\n</script>\n</body>\n</html>";
